//! Centralized non-secret configuration for Dark services.
//!
//! Walks up from CWD to find `config.toml` (or uses `MONOCLOUD_CONFIG` env
//! override) and layers environment variables on top, so BWS-injected
//! secrets override file values override hardcoded defaults.
//!
//! # Usage
//!
//! ```no_run
//! use dark_config::Config;
//!
//! let config = Config::load().unwrap();
//! println!("Supabase URL: {}", config.supabase.url);
//! println!("R2 bucket: {}", config.r2.bucket);
//! ```
//!
//! # Layering (figment)
//!
//! 1. `Config::default()` — hardcoded defaults (lowest priority)
//! 2. `config.toml` — file at repo root (or `MONOCLOUD_CONFIG` env override)
//! 3. `MONOCLOUD_*` env vars — BWS-injected secrets (highest priority)
//!
//! Env var names are prefixed `MONOCLOUD_` with nested fields separated by
//! `__` (double underscore). For example, `MONOCLOUD_SUPABASE__URL`
//! overrides `supabase.url` and `MONOCLOUD_R2__BUCKET` overrides `r2.bucket`.

#![allow(clippy::result_large_err)]

use figment::{
    Figment,
    providers::{Env, Format, Toml},
};
use serde::{Deserialize, Serialize};

/// Top-level config struct. All fields have defaults so a missing
/// `config.toml` or missing env vars never crash — services degrade
/// gracefully and fail at the point of use, not at config load.
#[derive(Debug, Clone, Default, Deserialize, Serialize)]
pub struct Config {
    #[serde(default)]
    pub supabase: SupabaseConfig,

    #[serde(default)]
    pub r2: R2Config,

    #[serde(default)]
    pub posthog: PostHogConfig,

    #[serde(default)]
    pub litellm: LitellmConfig,

    #[serde(default)]
    pub searxng: SearxngConfig,

    #[serde(default)]
    pub crawl4ai: Crawl4aiConfig,

    #[serde(default)]
    pub qdrant: QdrantConfig,

